const esc = (s) => String(s == null ? '' : s).replace(/'/g, "''");
const expected = ($input.first().json.value || '').trim();
const b = ($('Onboarding Webhook').first().json.body) || {};
const code = String(b.setup_code || '').trim();
const clientName = String(b.client_name || '').trim();
const repEmail = String(b.rep_email || '').trim();
const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(repEmail);
const valid = expected !== '' && code === expected && clientName !== '' && emailOk;
return [{ json: {
  valid,
  client_name: clientName,
  rep_email: repEmail,
  client_name_esc: esc(clientName),
  rep_email_esc: esc(repEmail),
  calendar_link_esc: esc(String(b.calendar_link || '').trim()),
  sender_account_esc: esc(String(b.sender_account || '').trim()),
  notes_esc: esc(String(b.notes || '').trim().slice(0, 1000)),
  raw_esc: esc(JSON.stringify({ client_name: b.client_name, rep_email: b.rep_email, calendar_link: b.calendar_link, sender_account: b.sender_account, notes: b.notes }))
} }];
